const HELLO={cycle:18,C:[6.0,5.8],r:1.3,top:.88,lap:[6.0,5.72],start:[6.04,5.76],hover:[5.88,5.97],kidSpot:[5.2,6.72],
dots:3.4,bloom:4.8,rise:5.6,up:7.0,bow:9.3,cheer:10.4,burst:10.55,five:11.05,calm:13.8,fade:16.5};
const helloClock=t=>fract(t/HELLO.cycle)*HELLO.cycle;
const helloRing=(deg,rho)=>{const a=deg*Math.PI/180;return [HELLO.C[0]+Math.cos(a)*rho,HELLO.C[1]+Math.sin(a)*rho]};
HELLO.cast={wonder:helloRing(195,1.5),elder:helloRing(238,1.5),sip:helloRing(280,1.5),lean:helloRing(335,1.6),point:helloRing(15,1.55),kid:helloRing(122,1.75)};
