function helloSpark(u){
const B=HELLO,[hi,hj]=B.hover,[si,sj]=B.start,[ki,kj]=B.kidSpot,zScreen=1.5,zHover=2.85,zKid=1.75;
const born=sstep(B.bloom,B.rise,u),gone=sstep(B.fade+.1,B.fade+1.1,u);
const rise=sstep(B.rise,B.up,u);
const look=sstep(B.up,B.up+.5,u)*(1-sstep(B.bow-.5,B.bow,u)),sway=look*Math.sin((u-B.up)*2.1)*.1;
const bow=bump(B.bow,B.bow+.7,u),bowZ=-.34*bow;
const cheer=sstep(B.cheer,B.cheer+.6,u)*(1-sstep(B.calm,B.calm+.8,u));
const visit=sstep(B.calm,B.calm+1.3,u),home=sstep(B.fade-.4,B.fade+.9,u);
let i=lerp(si,hi,rise)+sway,j=lerp(sj,hj,rise)-sway,z=lerp(zScreen,zHover,rise)+bowZ+cheer*.3;
i=lerp(i,ki,visit);j=lerp(j,kj,visit);z=lerp(z,zKid,visit);
i=lerp(i,si,home);j=lerp(j,sj,home);z=lerp(z,zScreen+.1,home);
const bob=rise*(1-home)*(.05+.06*visit);z+=Math.sin(u*1.7)*bob;i+=Math.sin(u*.9)*.03*visit*(1-home);j-=Math.sin(u*.9)*.03*visit*(1-home);
const glad0=B.calm+1.6,glad1=B.fade-.2;
const mood=u<B.up?'shy':u<B.cheer?'idle':u<B.calm?'happy':u<glad0?'listen':u<glad1?'happy':'listen';
let size=lerp(2.2,10.5,sstep(B.bloom,B.up-.2,u))*(1-.6*sstep(B.fade+.2,B.fade+1.1,u));
if(u>=B.up)size*=lerp(.82,1,sstep(B.up,B.up+.8,u));
if(u>=B.cheer&&u<B.calm)size*=lerp(1/1.1,1,sstep(B.cheer,B.cheer+.4,u));else if(u>=B.calm&&u<glad0)size*=lerp(1.1,1,sstep(B.calm,B.calm+.6,u));
else if(u>=glad0&&u<glad1)size*=lerp(1/1.1,1,sstep(glad0,glad0+.4,u));else if(u>=glad1)size*=lerp(1.1,1,sstep(glad1,glad1+.5,u));
const hopIn=sstep(glad0-.5,glad0,u)*(u<glad0?1:0),hopOut=(u>=glad1?1:0)*(1-sstep(glad1,glad1+.5,u)),hopEnd=(u>=B.calm?1:0)*(1-sstep(B.calm,B.calm+.7,u));
z+=Math.abs(Math.sin(u*5))*size*.6/32*(hopIn+hopOut+hopEnd);
return {i,j,z,opacity:born*(1-gone),size,mood,born,rise,cheer,visit,gone};
}
