const W=(x,y,z)=>H.p(b.i+x*ch-y*sh,b.j+x*sh+y*ch,.04+heave+pitch*x+roll*y+z);
const hull=[[.66,0],[.5,.17],[.2,.27],[-.2,.28],[-.52,.22],[-.62,.1],[-.62,-.1],[-.52,-.22],[-.2,-.28],[.2,-.27],[.5,-.17]];
