function wheelSlices(H,ci,cj,z0,p,th){
const n=8,sl=[],b=p.bend,RX=45.25,RY=22.6;
for(let k=0;k<=n;k++){const h=k/n,S=Math.pow(sstep(.3,1,h),1.5)*b,w=p.lean*h*h*(1-b);
const r=(lerp(p.r0,p.r1,h)+p.belly*Math.sin(Math.PI*h))*(1-.42*S);
const [x,y]=H.p(ci+w*Math.cos(th),cj+w*Math.sin(th),z0+p.hop+p.H*h*(1-.62*S));
sl.push([x+S*p.r1*RX*.72,y+S*p.r1*RY*.35,r*RX,r*RY*(1+.3*S)])}
return sl;
}
