function wheelHands(H,R,sl,k,mode,u,phase){
const hd=WHEEL.hands;if(!hd||!sl||k<=.02)return;
const [nh,fh,chest,sc]=hd,n=sl.length-1,tp=sl[n],bs=sl[0];
const skin=['coral',.55,'blue',.12],slv=['coral',.45,'blue',.12];
const hand=(x,y)=>{const C=circ(x,y,1.75*sc,10);H.fill(C,skin[0],skin[1],{fine:true});H.tint(C,skin[2],skin[3],{fine:true});H.outline(R,C,'blue',.7*Math.min(1.4,sc),{tone:.92,amp:.1})};
const arm=(a,b)=>{if(dist(a,b)<2)return;const P=ribbon([a,b],4.4*.42*sc*2);H.fill(P,slv[0],slv[1],{fine:true});H.tint(P,slv[2],slv[3],{fine:true});H.outline(R,P,'blue',.9*Math.min(1.4,sc),{tone:.92,amp:.1})};
const sh=[[chest[0]+7*sc*.7,chest[1]+2],[chest[0]-7*sc*.7,chest[1]+2]];
H.opacity(k,()=>{
if(mode==='hold'){
if(phase==='back')return;
let s=sl[n];for(let q=0;q<=n;q++)if(sl[q][1]<=nh[1]+3){s=sl[q];break}
const np=[s[0]-s[2]*.98,Math.max(s[1],tp[1]-tp[3]*.4)],fp=[tp[0]+tp[2]*.3,tp[1]-tp[3]*.3];
arm(nh,np);hand(np[0],np[1]);
{const d=[chest[0]-fp[0],chest[1]-fp[1]],L=Math.hypot(d[0],d[1])||1;arm([fp[0]+d[0]/L*8*sc,fp[1]+d[1]/L*8*sc],fp)}hand(fp[0],fp[1]);
}else if(mode==='wire'){
const v=sstep(19.7,20.35,u),y=bs[1]+2,x0=bs[0]+bs[2]*(1.25-2.5*v),x1=x0+bs[2]*1.4+8;
if(phase==='back'){arm(sh[1],[x1,y-1]);return}
H.line(R,curve([[x0,y],[(x0+x1)/2,y+2],[x1,y]],1),'blue',.9,{amp:.1});
for(const x of[x0,x1]){H.fill(rect(x-2.6,y-1.8,x+2.6,y+1.8),'sun',.95,{fine:true});H.outline(R,rect(x-2.6,y-1.8,x+2.6,y+1.8),'blue',.6)}
arm(nh,[x0,y-1]);hand(x0,y-2);hand(x1,y-2);
}else{
const np=[bs[0]-bs[2]*.9,bs[1]-4],fp=[bs[0]+bs[2]*.9,bs[1]-4];
if(phase==='back'){arm(sh[1],fp);return}
hand(fp[0],fp[1]);arm(sh[0],np);hand(np[0],np[1]);
}
});
}
