if(u<13.0){const k=(u-11.2)/1.8;return {...(k<.36?leg(T,M,k/.36):leg(M,K,(k-.36)/.64)),lift:0,face:'se'}}
if(u<17.2)return {i:K[0],j:K[1],lift:0,face:'se'};
if(u<19.0){const k=(u-17.2)/1.8;return {...(k<.64?leg(K,M,k/.64):leg(M,T,(k-.64)/.36)),lift:0,face:'nw'}}
