if(this.screens){const {a,j0,z0}=apartmentsCell(2,1);for(const [n,S] of this.screens.entries()){const rows=4;for(let r=0;r<rows;r++){const id=Math.floor(t*1.3+n*7)-r,Q=streamOf('apartments','code',id),w=S.w1-(r+.5)*(S.w1-S.w0)/rows,len=rd(Q,.2,.7)*(S.u1-S.u0-.1),ind=ri(Q,0,2)*.08;
H.fill(ribbon([H.p(a+S.u0+.05+ind,j0+.31,z0+w),H.p(a+S.u0+.05+ind+len,j0+.31,z0+w)],1.6),pk(Q,['teal','paper','sun','teal']),.9,{fine:true})}}}
