{const {a,j0,z0}=apartmentsCell(0,1),[gx,gy]=H.p(a+1.9,j0+1.05,z0+.9);for(let k=0;k<3;k++){const ph=fract(t*.55+k/3);H.line(R,arcPts(gx,gy-4,6+ph*16,5+ph*13,-1.2,.5,8),k%2?'sun':'coral',1.1,{amp:.2,tone:.85*(1-ph)*sstep(0,.15,ph)})}}
if(this.canvas){const [cx,cy]=centroid(this.canvas);H.clip(this.canvas,()=>{for(const [k,[dx,dy,dx2,dy2,ink]] of [[-9,8,4,2,'coral'],[6,-2,10,9,'coral'],[-10,-6,-2,-9,'blue']].entries()){const al=sstep(6+k*2.4,7.2+k*2.4,u)*(1-sstep(14.6,15,u));if(al>.02)H.line(R,[[cx+dx,cy+dy],[cx+dx2,cy+dy2]],ink,2.4,{amp:.3,tone:.9*al})}})}
