{const pl=fract(t/27);if(pl<.55&&fract(t*1.4)<.4){const [wx,wy]=wallPt(H,'ne',.6+pl*19,8.95,.05);H.dot(wx,wy,1.3,'coral',1,{knock:true});H.dot(wx+5,wy+1,.8,'paper',1)}}
for(let k=0;k<(this.cityWin||[]).length;k+=5){if(fract(t/11+k*.17)<.3)H.fill(this.cityWin[k],'blue',1)}
