const DOOR=(()=>{
const cycle=20,rest=FIGURES.clips.idle.keys[0][1];
const seat={drop:.47,ll:84,lr:80,kl:-84,kr:-80};
const clip=(name,dur,keys)=>{FIGURES.clips[name]={dur,keys:keys.map(([s,p])=>[s,{...rest,...p}])}};
clip('doorSitDown',1,[[0,{al:-6,ar:10,el:-4,er:4}],[1,{...seat,al:20,ar:28,el:30,er:30}]]);
const W1={...seat,al:20,el:30,ar:145,er:20,head:-4},W2={...seat,al:20,el:30,ar:158,er:-25};
clip('doorSitWave',1.2,[[0,W1],[.25,W2],[.5,W1],[.75,W2],[1,W1]]);
const path=[[4.6,8.6,-.5],[5.25,8.55,.3],[7.15,8.2,2.4],[9.0,7.3,4.55]];
const D=[0];for(let k=1;k<path.length;k++)D[k]=D[k-1]+Math.hypot(path[k][1]-path[k-1][1],path[k][2]-path[k-1][2]);
const stride=D[3]/(Math.round(D[3]/.95)+.25);
return {cycle,path,D,stride,
door:{p0:7.85,p1:8.95,h:2.3,aMax:1.5},
table:{i:5.0,j:5.6,w:4.0,d:1.5,z:.88},
seat:[6.7,5.05],seat2:[9.55,6.35],hw:.34,
win:{j0:1.7,j1:5.9,z0:.95,z1:3.0},sun:{di:1.85,dj:.5},
paper:[7.55,6.45],greet:[6.45,5.7],cat:[3.4,4.5],
sitAt:9.0,seated:9.7,waveAt:10.4,waveEnd:12.6,fadeAt:13.6,fadeEnd:15.4,
types:['dog','guitar','child','elder','box'],
skins:[['coral',.22],['coral',.3,'sun',.15],['coral',.55,'blue',.12],['coral',.75,'blue',.3],['coral',.42,'sun',.1]],
hairs:[['blue',.9],['coral',.8,'blue',.4],['sun',.9,'coral',.3],['blue',.55],['coral',.6,'blue',.2]],
shirts:[['teal',.75],['coral',.7],['sun',.85],['blue',.7],['teal',.45],['coral',.45,'sun',.2],['paper',1]],
pants:[['blue',.75],['blue',.5],['coral',.55],['teal',.6],['sun',.4,'coral',.2]],
};
})();
const doorU=t=>fract(t/DOOR.cycle)*DOOR.cycle;
const doorLoop=t=>Math.floor(t/DOOR.cycle);
const doorType=L=>DOOR.types[((L%5)+5)%5];
const doorBeat=u=>({
nudge:sstep(.8,2.2,u),
open:sstep(3.0,5.4,u)*(1-sstep(15.6,18.0,u)),
turned:sstep(DOOR.seated,DOOR.seated+.7,u),
greet:sstep(DOOR.seated+.1,DOOR.seated+.6,u)*(1-sstep(DOOR.fadeAt+.5,DOOR.fadeAt+1.2,u)),
greetPos:sstep(DOOR.seated-.3,DOOR.seated+.4,u)*(1-sstep(DOOR.fadeAt+1.0,DOOR.fadeAt+2.4,u)),
awake:sstep(3.6,4.2,u)*(1-sstep(15.4,16.0,u)),
});
function doorWalker(u,lag=0,end=null){
const P=DOOR.path,D=DOOR.D,v=u-lag;
if(v<P[0][0])return null;
const last=end||[P[3][1],P[3][2]];
if(v<P[3][0]){let k=1;while(k<P.length-1&&v>P[k][0])k++;const a=P[k-1],b=P[k],f=(v-a[0])/(b[0]-a[0]);
const bi=k===P.length-1?last[0]:b[1],bj=k===P.length-1?last[1]:b[2],j=lerp(a[2],bj,f);
return {i:lerp(a[1],bi,f),j,face:FIGURES.facing(bi-a[1],bj-a[2]),clip:'walk',phase:lerp(D[k-1],D[k],f)/DOOR.stride,inDoor:j<.3,walking:true,arrived:0}}
return {i:last[0],j:last[1],face:'sw',clip:'idle',phase:v/3,inDoor:false,walking:false,arrived:v-P[3][0]};
}
function doorVisitor(u){
const K=DOOR;if(u<K.path[0][0]||u>K.fadeEnd)return null;
const op=sstep(4.6,5.0,u)*(1-sstep(K.fadeAt,K.fadeEnd,u));
if(u<K.sitAt)return {...doorWalker(u),opacity:op,sitf:0};
const [si,sj]=K.seat;
if(u<K.seated){const f=(u-K.sitAt)/(K.seated-K.sitAt),g=sm(f);return {i:lerp(7.3,si,g),j:lerp(4.55,sj,g),face:'sw',clip:'doorSitDown',phase:Math.min(.999,f),opacity:op,inDoor:false,walking:false,sitf:g}}
const wave=u>K.waveAt&&u<K.waveEnd;
return {i:si,j:sj,face:'sw',clip:wave?'doorSitWave':'sit',phase:wave?(u-K.waveAt)/1.2:(u-K.seated)/3,opacity:op,inDoor:false,walking:false,sitf:1};
}
function doorLook(L,slot){
const K=DOOR,Q=streamOf('door','look',L,slot),o={skin:pk(Q,K.skins),hair:pk(Q,K.hairs),shirt:pk(Q,K.shirts),pants:pk(Q,K.pants),hairStyle:pk(Q,['short','long','bun','curly','cap','pony']),glasses:ch(Q,.25),shoe:pk(Q,[['blue',.9],['coral',.7],['paper',1]])};
if(slot==='elder'){o.hair=pk(Q,[['paper',1,'blue',.2],['blue',.35],['paper',1,'sun',.15]]);o.hairStyle=pk(Q,['bald','bun','short']);o.glasses=ch(Q,.7)}
if(slot==='child'){o.shirt=pk(Q,[['sun',.9],['coral',.75],['teal',.7]]);o.pants=pk(Q,[['blue',.7],['coral',.5],['teal',.5]]);o.hairStyle=pk(Q,['short','curly','pony','cap']);o.glasses=false}
return o;
}
